SELECT ?e ?name ?ts ?tid WHERE {
  ?e rdfs:label ?name .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
  ?e ref:hasExternalReference ?ts .
  ?ts ref:hasTimeseriesId ?tid .
}

SELECT ?label WHERE {
  ?e rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "chiller") || CONTAINS(LCASE(?label),"condpump") || CONTAINS(LCASE(?label),"pump"))
}

SELECT ?e ?tsid WHERE {
  { ?e rdfs:label "Chiller02" } UNION { ?e rdfs:label "CondPump01" } UNION { ?e rdfs:label "CondPump02" }
  ?e brick:hasExternalReference ?ts .
  ?ts ref:hasTimeseriesId ?tsid .
}

SELECT ?e ?o WHERE {
  { ?e rdfs:label "Chiller02" } UNION { ?e rdfs:label "CondPump01" }
  ?e ?p ?o .
  FILTER(?p != rdf:type)
}

SELECT ?point ?o WHERE {
  ?point ?p ?o .
  FILTER(STRCONTAINS(STR(?point),"_Electric_Power_Sensor") && (STRCONTAINS(STR(?point),"Chiller02") || STRCONTAINS(STR(?point),"CondPump")))
  FILTER(?p = ref:hasExternalReference || STRSTARTS(STR(?p),"urn:"))
}

